 "Betonung verändert alles": "Emphasis changes everything",
 "Bevor du eine Endung suchst, stell die Frage: Wem gebe ich es? → Dativ. Mit wem gehe ich? → Instrumental. Wo bin ich? → Präpositiv. Die Frage IST die Regel.": "Before you look for an ending, ask the question: To whom am I giving it? → Dative. With whom am I going? → Instrumental. Where am I? → Prepositional. The question IS the rule.",
 "Bewegungspräfixe: при-, у-, в-, вы-": "Motion prefixes: при-, у-, в-, вы-",
