 "Bitten, wünschen, entscheiden": "Requesting, wishing, deciding",
 "Blick nach vorn": "Looking ahead",
 "Blumen schenkt man in Russland nur in UNGERADER Zahl – gerade Zahlen gehören zur Beerdigung.": "In Russia, flowers are only given in ODD numbers – even numbers are for funerals.",
 "Brot (хлеб) ist in Russland heilig – Brot wegzuwerfen galt lange als eine der schlimmsten Sünden im Haushalt.": "Bread (хлеб) is sacred in Russia – throwing away bread was long considered one of the worst household sins.",
 "Bruder ohne Blut": "Brother without blood",
 "Bücher stehen (стоят), Zeitungen liegen (лежат) – Russisch beschreibt Gegenstände nach ihrer Form.": "Books stand (стоят), newspapers lie (лежат) – Russian describes objects based on their form.",
 "Café-Sprache: bestellen mit Chunks": "Café language: ordering with chunks",
 "Chat mit Freunden: *Привет! Ок, спишемся.* Kollegen: *Добрый день! Принято.* Offiziell: *Уважаемый Пётр Сергеевич! С уважением.*": "Chat with friends: *Привет! Ок, спишемся.* Colleagues: *Добрый день! Принято.* Official: *Уважаемый Пётр Сергеевич! С уважением.*",
