 "Der Trick bei Konsonanten-Türmen: einfach einen verschlucken. In *здравствуйте* spricht niemand das erste в – „sdrástwujte“. In *счастье* klingt сч wie щ: „schtschástje“.": "The trick with consonant towers: just swallow one. In *здравствуйте*, no one pronounces the first в – \"zdrástvuytye\". In *счастье*, сч sounds like щ: \"shchástye\".",
