 "Der volle Spruch endet mit „…во рту росли бы грибы\" – „dann würden im Mund Pilze wachsen\". Die russische Art zu sagen: Aufhören zu träumen.": "The full saying ends with \"…во рту росли бы грибы\" – \"then mushrooms would grow in your mouth\". The Russian way of saying: Stop dreaming.",
