 "Deutsche schreiben oft zu knapp. Ein russischer Geschäftsbrief darf ruhig mit *Добрый день!* beginnen und mit *Заранее спасибо* enden – Wärme gehört dazu.": "English speakers often write too briefly. A Russian business letter can comfortably start with *Добрый день!* and end with *Заранее спасибо* – warmth is part of it.",
