 "Die größte Hürde des Russischen liegt hinter dir: *делать* gegen *сделать*, *читать* gegen *прочитать*. Es geht nicht um lang oder kurz, sondern um die Perspektive – Film oder Foto, Verlauf oder Ergebnis. Weil der perfektive Aspekt keine Gegenwart haben kann, sieht seine Präsensform aus wie Gegenwart und bedeutet Zukunft: *я сделаю*.": "The biggest hurdle in Russian is behind you: *делать* versus *сделать*, *читать* versus *прочитать*. It's not about long or short, but about perspective – film or photo, ongoing or completed. Because the perfective aspect can't have a present tense, its present form looks like present but means future: *я сделаю*.",
