 "Die indirekte Rede funktioniert im Russischen einfacher als im Deutschen: Die Zeitform bleibt, wie sie war. *Он сказал: «Я приду»* wird zu *Он сказал, что придёт* – keine Konjunktivakrobatik. Und für indirekte Fragen hast du die Partikel *ли*: *Он спросил, приду ли я.*": "Indirect speech is simpler in Russian than in English: The tense stays the same. *Он сказал: «Я приду»* becomes *Он сказал, что придёт* – no need for complex subjunctive forms. For indirect questions, you have the particle *ли*: *Он спросил, приду ли я.*",
