 "Die Rechnung heißt *счёт* – mit dem ё, das du kennst. *Счёт, пожалуйста!* ist der wichtigste Satz am Ende jedes Essens. Trinkgeld: rund 10 %, liegt auf dem Tisch.": "The bill is called *счёт* – with the ё you know. *Счёт, пожалуйста!* is the most important phrase at the end of every meal. Tip: around 10%, left on the table.",
