 "Die russische Vergangenheit ist einfacher als die Gegenwart: eine einzige Endung auf *-л*, angepasst an das Geschlecht – *я работал*, *она работала*, *мы работали*. Kein Hilfsverb, keine Umstellung bei Fragen. Damit erzählst du deinen gestrigen Tag, eine Reise oder eine Panne.": "The Russian past tense is simpler than the present: a single ending *-л*, adjusted for gender – *я работал*, *она работала*, *мы работали*. No auxiliary verb, no word order change for questions. With this, you can talk about your day yesterday, a trip, or a mishap.",
 "Die russische Vergangenheit richtet sich nach dem Geschlecht – man hört sofort, ob ein Mann oder eine Frau spricht.": "The Russian past tense depends on gender – you can immediately tell if a man or a woman is speaking.",
 "Die russische Woche beginnt am Montag – понедельник heißt wörtlich „der Tag nach dem Nichtstun“ (воскресенье = Sonntag).": "The Russian week starts on Monday – понедельник literally means \"the day after doing nothing\" (воскресенье = Sunday).",
 "Die Schilder-Vier": "The Sign Four",
 "Die Schreibregel nach г, к, х, ж, ш, щ, ч kennen": "Knowing the Spelling Rule After г, к, х, ж, ш, щ, ч",
 "Die Schulregel „einmal = идти, mehrmals = ходить\" führt in die Irre. Entscheidend ist die PERSPEKTIVE: Bin ich unterwegs (идти) oder beschreibe ich eine Gewohnheit bzw. einen abgeschlossenen Hin-und-Rückweg (ходить)?": "The school rule 'once = идти, multiple times = ходить' is misleading. The key is PERSPECTIVE: Am I on my way (идти) or describing a habit or a completed round trip (ходить)?",
