 "Die Unterscheidung belebt/unbelebt ist im Russischen Grammatik: Ein Toter gilt sprachlich als belebt, eine Puppe nicht.": "The distinction between animate/inanimate is a grammatical feature in Russian: a dead person is considered animate linguistically, a doll is not.",
