 "Die vier Formen, an denen jeder Zeitungsartikel hängt: das kurze passive (*сделано*), das vollständige passive (*построенный дом*), das aktive (*работающий человек*) und das Adverbialpartizip (*прочитав книгу*). Du sprichst sie selten – aber du liest sie jetzt, ohne zu stolpern.": "The four forms that every newspaper article relies on: the short passive (*сделано*), the full passive (*построенный дом*), the active (*работающий человек*), and the adverbial participle (*прочитав книгу*). You rarely speak them – but now you read them without stumbling.",
 "Die vier Unregelmäßigen": "The four irregulars",
 "Die Vokale *я, е, ё, ю, и* machen den Konsonanten davor weich – zusätzlich das stille *ь* aus Lektion 7. *лук* = hart („luk“), *люк* = weich („ljuk“, die Luke). Zwei Wörter!": "The vowels *я, е, ё, ю, и* soften the preceding consonant – additionally the silent *ь* from Lesson 7. *лук* = hard ('luk'), *люк* = soft ('lyuk', the hatch). Two different words!",
