 "Die Zisch-Familie": "The Hissing Family",
 "Die Zischlaute Ж, Ч, Ш, Щ, Ц unterscheiden": "Distinguishing the Hissing Sounds Ж, Ч, Ш, Щ, Ц",
 "Die Zischlaute in echten Wörtern sprechen": "Pronouncing sibilants in real words",
 "Die zusammengesetzte Zukunft mit буду": "The compound future with буду",
 "Die zwei Zukünfte": "The two futures",
 "Die zwei Zukünfte im Vergleich": "Comparing the two futures",
 "Die zweite Zukunftsform – ohne буду": "The second future form – without буду",
 "Diese Ansage hörst du in jeder Metro: *Осторожно, двери закрываются!* – „Vorsicht, die Türen schließen!\" Ein Satz, den jeder Russlandbesucher hundertmal hört.": "You hear this announcement on every metro: *Осторожно, двери закрываются!* – \"Caution, the doors are closing!\" A sentence every visitor to Russia hears hundreds of times.",
 "Diese Buchstaben tragen Masken: *В* = W, *Н* = N, *Р* = R, *С* = S, *У* = U, *Х* = ch. *вот* liest sich „wot“, *нос* ist „nos“. Merk dir: Nicht dem Aussehen trauen, dem Klang!": "These letters wear masks: *В* = V, *Н* = N, *Р* = R, *С* = S, *У* = U, *Х* = ch. *вот* is read as \"vot\", *нос* is \"nos\". Remember: Don't trust appearances, trust the sound!",
 "Diese Lektion übt Wörter, keine medizinischen Ratschläge. Bei echten Beschwerden gilt überall dasselbe: zum Arzt gehen.": "This lesson practices words, not medical advice. For real complaints, the same rule applies everywhere: go to the doctor.",
 "Diese vier musst du am Anfang nicht aktiv benutzen – aber du hörst sie ständig. Ziel dieser Lektion: verstehen, wenn jemand sie sagt.": "You don't need to actively use these four at the beginning – but you'll hear them all the time. Goal of this lesson: understand when someone says them.",
 "Diese Wendungen hört man ständig. Wer sie wörtlich nimmt, versteht nichts – *Речь идёт о деньгах* hat nichts mit Gehen zu tun.": "These phrases are heard all the time. If you take them literally, you won't understand – *Речь идёт о деньгах* has nothing to do with walking.",
 "Diese Wendungen sind schriftsprachlich. Im Gespräch sagt man *из-за* statt *в связи с* und *хотя* statt *несмотря на то что*.": "These expressions are formal written language. In conversation, you would say *из-за* instead of *в связи с* and *хотя* instead of *несмотря на то что*.",
 "Dieselbe Entscheidung wie im Deutschen – nur triffst du sie öfter falsch herum.": "A choice English makes too – but in Russian you will often need it the other way round.",
 "Dieselbe Logik": "The same logic",
 "Dieselbe Person!": "The Same Person!",
 "Dieselbe Präposition, zwei Fälle: *Я в театре* (wo? Präpositiv) gegen *Я иду в театр* (wohin? Akkusativ). Genauso *дома* und *домой*, *там* und *туда*. Russisch trennt Aufenthalt und Ziel strenger als das Deutsche – und du hörst den Unterschied jetzt.": "The same preposition, two cases: *Я в театре* (where? prepositional) versus *Я иду в театр* (where to? accusative). Similarly, *дома* and *домой*, *там* and *туда*. Russian distinguishes between location and destination more strictly than English – and now you can hear the difference.",
 "Dieselbe Regel": "The same rule",
 "Dieselben Wörter, andere Aussage": "Same Words, Different Meaning",
 "Dieselben Wörter, andere Botschaft": "Same words, different message",
