 "Dinge und Menschen beschreiben": "Describing Things and People",
 "Dinge und Menschen vergleichen": "Comparing things and people",
 "Direkt: *„Я приду.\"* Indirekt: *Он сказал, что придёт.* Die Zeitform bleibt, wie sie war – Russisch kennt keine Zeitenfolge wie das Englische oder die deutsche indirekte Rede.": "Direct: *„Я приду.\"* Indirect: *Он сказал, что придёт.* The tense stays as it was – Russian has no sequence of tenses like English does.",
