 "Einen Termin nennen": "Setting an appointment",
 "Einen Termin vereinbaren": "Making an appointment",
 "Einen Text schreiben": "Writing a Text",
 "Einen Vortrag strukturieren": "Structuring a Presentation",
 "Einen Zeitplan nachvollziehen": "Following a Schedule",
 "Einen zusammenhängenden Text lesen": "Read a connected text",
 "Einer, viele": "One, Many",
 "Eingebettete Fragen behalten ihr Fragewort": "Embedded Questions Keep Their Question Word",
 "Eingebettete Fragen bilden": "Forming Embedded Questions",
 "Einkaufen & Vergangenheit": "Shopping & The Past",
 "Einkaufen gehen": "Going shopping",
 "Einkaufen, Krankheit, Absage – und der Bericht danach": "Shopping, illness, cancellation – and the report afterwards",
 "Einladen & absagen": "Inviting & declining",
 "Einladen mit imperfektiv": "Inviting with the imperfective",
 "Einladen, zusagen, absagen": "Inviting, accepting, declining",
 "Einladung von Anweisung unterscheiden": "Distinguishing Invitation from Instruction",
 "Einladungen aussprechen": "Making invitations",
 "Einräumungen formulieren": "Formulating Concessions",
 "Eins oder viele?": "One or many?",
 "Endet ein Wort auf Konsonant → männlich (*диван*, *парень*). Auf *-а/-я* → weiblich (*лампа*, *девушка*). Auf *-о/-е* → sächlich (*зеркало*, *поле*). Das Wortende sagt dir, ob он, она oder оно.": "If a word ends in a consonant → masculine (*диван*, *парень*). Ends in *-а/-я* → feminine (*лампа*, *девушка*). Ends in *-о/-е* → neuter (*зеркало*, *поле*). The word ending tells you whether to use он, она or оно.",
 "Entfernungen und Zwecke ausdrücken": "Expressing distances and purposes",
 "Entschuldigen, bitten, um Erlaubnis fragen": "Apologising, asking, requesting permission",
 "Er fragte, ob…": "He asked whether…",
 "Er sagte, dass…": "He said that…",
 "Er, sie oder es?": "He, she or it?",
 "er, sie, wir und die anderen kennen": "Getting to know he, she, we and the others",
 "Erfolge nennen": "Mentioning Achievements",
 "Erfolglose Versuche ausdrücken": "Expressing unsuccessful attempts",
 "Ergänzungssätze mit что, где, как": "Complement clauses with что, где, как",
 "Ergebnisse ausdrücken": "Expressing results",
 "Ergebnisse festhalten": "Recording outcomes",
 "Ergebnisse in der Zukunft ausdrücken": "Expressing results in the future",
 "Erlaubnis, Verbot und Notwendigkeit": "Permission, prohibition, and necessity",
 "Eröffnen, nachfragen, zusammenfassen": "Opening, asking questions, summarising",
 "Errungenschaften konkret": "Concrete Achievements",
 "Erschließen statt lernen": "Infer instead of learn",
 "Erst Adjektiv, dann Wort": "First the Adjective, Then the Word",
 "Erst die Zeitwörter suchen (*утром, в восемь, потом, вечером*) – sie geben das Gerüst. Dann die Orte (*в кафе, в Кремль, на площади*). Der Rest ergibt sich. Du musst nicht jedes Wort kennen.": "First, find the time words (*утром, в восемь, потом, вечером*) – they provide the framework. Then, look for the places (*в кафе, в Кремль, на площади*). The rest will follow. You don't need to know every word.",
 "Erst erkennen reicht": "Recognising is enough at first",
 "Erst erkennen, dann bilden": "First recognise, then form",
 "Erst grob, dann fein": "First Broadly, Then in Detail",
 "Erst HÖREN lernen, dann sprechen: Die Übungen gleich spielen dir Paare vor. Wenn dein Ohr hart und weich trennt, folgt der Mund von ganz allein.": "First learn to LISTEN, then speak: The exercises will play pairs for you. Once your ear distinguishes hard and soft, your mouth will naturally follow.",
 "Erst wenn du das Gehörte in eigenen Worten wiedergeben kannst, hast du es wirklich verstanden. *В двух словах…* – so fängst du an.": "Only when you can recount what you've heard in your own words have you truly understood it. *В двух словах…* – that's how you start.",
 "Erste Gespräche": "First Conversations",
 "Erstens: Wer erzählt und über welchen Tag? Zweitens: Was passierte zuerst, was danach? Drittens: Zahlen und Uhrzeiten. Nie alles auf einmal wollen.": "First: Who is telling the story and about which day? Second: What happened first, and what followed? Third: Numbers and times. Never try to get everything at once.",
 "Erster Durchgang: Wer kommt zu wem? Zweiter: Was bringen sie mit? Dritter: Was planen sie danach? Die Fälle geben dir die Antworten – *к ним, с тортом, для мамы*.": "First round: Who is visiting whom? Second: What are they bringing? Third: What are their plans afterwards? The cases give you the answers – *к ним, с тортом, для мамы*.",
 "Erstes Kennenlernen": "First meeting",
 "Erzählen & Meinungen": "Narration & opinions",
 "Erzählen wie ein Muttersprachler": "Narrating like a native speaker",
 "Erzählen, begründen, diskutieren": "Narrating, justifying, discussing",
 "Erzählungen strukturieren": "Structuring narratives",
 "Es gibt hier…": "There is…",
 "Es wird gebaut": "It is being built",
 "Etwa 90 Prozent der russischen Verben haben einen Aspektpartner – die restlichen zehn muss man einzeln lernen.": "About 90 percent of Russian verbs have an aspect partner – the remaining ten percent need to be learned individually.",
 "Etwas tragen": "Carrying something",
