 "Feste Verbindungen kennen": "Knowing fixed expressions",
 "Film oder Foto": "Film or photo",
 "Film oder Foto?": "Film or photo?",
 "Finales Projekt": "Final Project",
 "Flexibel reagieren": "Reacting Flexibly",
 "Fokus durch Umstellung setzen": "Set focus by rearranging",
 "Fokus setzen": "Setting the focus",
 "Formell schreiben": "Writing formally",
 "Formelle E-Mails": "Formal Emails",
 "Formelle E-Mails aufbauen": "Structuring Formal Emails",
 "Formelle Texte lesen": "Reading Formal Texts",
 "Formelle Wendungen für Texte": "Formal Phrases for Texts",
 "Formelles und informelles Register": "Formal and Informal Register",
 "Fortgeschrittene Vergleiche": "Advanced comparisons",
 "Fortgeschrittenes Zahlentraining": "Advanced number training",
 "Frag dich: „Geht es um das ERGEBNIS oder um die TÄTIGKEIT?\" Ergebnis → perfektiv (*сделаю*). Tätigkeit, Dauer, Wiederholung → *буду* + imperfektiv (*буду делать*).": "Ask yourself: \"Is it about the RESULT or the ACTIVITY?\" Result → perfective (*сделаю*). Activity, duration, repetition → *буду* + imperfective (*буду делать*).",
 "Fragen & kleine Antworten": "Questions & Short Answers",
 "Fragen in Sätze einbauen": "Embedding questions into sentences",
 "Fragen ohne Hilfsverb stellen": "Ask questions without an auxiliary verb",
 "Fragen ohne Umbau": "Questions Without Rearranging",
 "Fragen und Verneinung in der Vergangenheit": "Questions and Negation in the Past",
 "Fragewörter bleiben": "Question words remain",
 "Fragewörter einbetten": "Embedding question words",
 "Frauen bleiben normal": "Women Stay the Same",
 "Frei sprechen üben": "Practising Speaking Freely",
 "Freunde und Familie vorstellen": "Introducing friends and family",
 "Freundlich reagieren": "Reacting Kindly",
 "Fristen, Risiken, Kompromisse": "Deadlines, risks, compromises",
 "Fünf Fragen stellen und beantworten": "Ask and answer five questions",
 "Für Diagramme": "For diagrams",
 "Für Verlauf (*Завтра буду работать весь день*), Wiederholung (*Буду ходить в спортзал*) und Zustände (*Буду дома*). Also: alles ohne klaren Endpunkt.": "For ongoing actions (*Завтра буду работать весь день*), repetition (*Буду ходить в спортзал*), and states (*Буду дома*). Basically, anything without a clear endpoint.",
 "Für Werkzeug, Begleitung und Beruf gibt es einen eigenen Fall: den Instrumental.": "For tools, accompaniment, and profession, there's a special case: the instrumental.",
 "Ganze Alltagswörter flüssig entziffern": "Effortlessly decipher everyday words",
 "Gegensatz und Einräumung": "Contrast and Concession",
 "Gehen ist nicht gleich gehen": "Walking isn't just walking",
 "Gehörtes sicher zuordnen und schreiben": "Confidently match and write what you hear",
