 "Genitiv, Dativ, Instrumental": "Genitive, Dative, Instrumental",
 "Genitiv: *-ого/-ой* (*нового друга, хорошей подруги*). Dativ: *-ому/-ой* (*старому другу*). Instrumental: *-ым/-ой* (*с новым коллегой*).": "Genitive: *-ого/-ой* (*нового друга, хорошей подруги*). Dative: *-ому/-ой* (*старому другу*). Instrumental: *-ым/-ой* (*с новым коллегой*).",
