 "Handlungen auf der Zeitachse ordnen": "Arranging Actions on the Timeline",
 "Handy: Einstellungen → Tastatur → Russisch hinzufügen. Ab jetzt kannst du auf Russisch tippen – und ab dieser Lektion fragt dich das Diktat genau das ab.": "Phone: Settings → Keyboard → Add Russian. Now you can type in Russian – and from this lesson, the dictation will test you on it.",
