 "Preise, Busnummern, Uhrzeiten – Zahlen sind das Erste, was du „in freier Wildbahn“ verstehst. Achte auf *пять* (5) und *десять* (10), die hörst du ständig.": "Prices, bus numbers, times – numbers are the first thing you understand \"in the wild\". Pay attention to *пять* (5) and *десять* (10), you'll hear them all the time.",
