 "Register bewusst wählen": "Consciously choosing the register",
 "Register erkennen": "Recognising register",
 "Register ist keine Nebensache: *Здравствуйте* oder *привет*, *не могли бы вы* oder *дай*. Dazu die *-ся*-Konstruktion fürs Unpersönliche (*здесь строится дом*), Wortfamilien zum Erschließen unbekannter Wörter und Zahlen im Geschäftskontext. Nachricht und Podcast verstehst du im Kern.": "Register is not a side issue: *Здравствуйте* or *привет*, *не могли бы вы* or *дай*. Plus the *-ся* construction for impersonal expressions (*здесь строится дом*), word families to deduce unknown words, and numbers in a business context. You understand the core of news and podcasts.",
 "Register unterscheiden": "Distinguishing Register",
 "Register: du oder Sie": "Addressing: you or you?",
 "Reihenfolge und Details erfassen": "Grasping order and details",
 "Reihenfolgen bauen": "Building sequences",
 "Reihenfolgen mit сначала/после этого": "Sequences with сначала/после этого",
 "Rein, raus, an, weg": "In, out, to, away",
 "Relativsätze mit который": "Relative Clauses with который",
 "Richtung und Ort auseinanderhalten": "Distinguishing direction and location",
 "Richtungsangaben verstehen": "Understanding Directions",
 "Rolle, Beruf und Werkzeug – derselbe Fall": "Role, profession, and tool – the same case",
 "Routen genau beschreiben": "Describing routes precisely",
 "Ruhe wirkt": "Stay calm",
 "Russen fragen selten „Was machst du beruflich?“ – eher „Wo arbeitest du?“ (Где ты работаешь?).": "Russians rarely ask \"What do you do for a living?\" – more often \"Where do you work?\" (Где ты работаешь?).",
 "Russen haben drei Namen: Vorname, Vatersname, Nachname. Anna Iwanowna ist „Anna, Tochter des Iwan“.": "Russians have three names: first name, patronymic, surname. Anna Ivanovna is 'Anna, daughter of Ivan'.",
 "Russen nennen enge Freunde oft „Bruder\" oder „Schwester\" – Familie ist mehr als Blutsverwandtschaft.": "Russians often call close friends \"brother\" or \"sister\" – family is more than just blood relations.",
 "Russen sagen nicht „ich habe Hunger“, sondern *я хочу есть* (ich will essen) und *я хочу пить* (ich will trinken). Zwei Sätze, die dich durch jeden Tag bringen.": "Russians don't say 'I'm hungry', but *я хочу есть* (I want to eat) and *я хочу пить* (I want to drink). Two phrases to get you through any day.",
 "Russen sagen nicht „ich und mein Freund\", sondern *мы с другом* – „wir mit dem Freund\". Klingt seltsam, ist aber die normale Form.": "Russians don't say \"I and my friend\", but *мы с другом* – \"we with the friend\". It sounds unusual, but it's the normal form.",
 "Russen sagen oft *Я тебя вижу* statt *Я вижу тебя*. Beides ist richtig – das Pronomen rutscht gern nach vorn, besonders in der gesprochenen Sprache.": "Russians often say *Я тебя вижу* instead of *Я вижу тебя*. Both are correct – the pronoun likes to move forward, especially in spoken language.",
 "Russen verneinen gern doppelt: Я никогда не… (ich nie nicht…) ist völlig korrekt – und Pflicht!": "Russians often use double negatives: Я никогда не… (I never don't…) is completely correct – and required!",
 "Russisch braucht kein Hilfsverb – „Hast du gearbeitet?\" ist einfach Ты работал?": "Russian doesn't need an auxiliary verb – \"Did you work?\" is simply Ты работал?",
 "Russisch hat kein Verb für „haben\" – man sagt wörtlich „bei mir ist\".": "Russian doesn't have a verb for \"to have\" – you literally say \"at me is\".",
 "Russisch im Berufsleben": "Russian in professional life",
 "Russisch in freier Wildbahn": "Russian in the Wild",
 "Russisch in verschiedenen Kontexten": "Russian in different contexts",
 "Russisch ist Amtssprache in mehreren Ländern – und klingt in Kasachstan anders als in Sankt Petersburg.": "Russian is an official language in several countries – and it sounds different in Kazakhstan than in Saint Petersburg.",
 "Russisch kennt kein Verb für „haben\" – es sagt *у меня есть брат*, wörtlich „bei mir ist ein Bruder\". Und die Verneinung wechselt den Fall: *у меня нет машины*. Genau solche Stellen zeigen, dass Russisch nicht Deutsch mit anderen Wörtern ist, sondern eine eigene Logik hat.": "Russian doesn't have a verb for \"to have\" – it says *у меня есть брат*, literally \"by me is a brother\". And the negation changes the case: *у меня нет машины*. These examples show that Russian isn't just English with different words, but has its own logic.",
 "Russisch lässt „ist/bin/sind“ in der Gegenwart einfach weg: *Я студент* – „Ich (bin) Student“. *Он дома* – „Er (ist) zu Hause“. Weniger Wörter, gleiche Aussage.": "Russian simply leaves out \"is/am/are\" in the present tense: *Я студент* – \"I (am) a student\". *Он дома* – \"He (is) at home\". Fewer words, same meaning.",
 "Russisch sprechen rund 250 Millionen Menschen – es ist die meistgesprochene Muttersprache Europas.": "Around 250 million people speak Russian – it's the most widely spoken native language in Europe.",
 "Russisch steckt voller internationaler Wörter: *кофе*, *метро*, *такси*, *банк*, *спорт*. Sie klingen fast wie im Deutschen – nur die Schrift ist neu. Genau die knackst du in den nächsten drei Lektionen.": "Russian is full of international words: *кофе*, *метро*, *такси*, *банк*, *спорт*. They sound almost the same as in English – only the script is new. You'll crack it in the next three lessons.",
 "Russisch stellt Bekanntes nach vorn und Neues nach hinten. *Вчера пришёл Иван* (wer kam? – Iwan) gegen *Иван пришёл вчера* (wann kam er? – gestern).": "Russian places known information at the front and new information at the back. *Вчера пришёл Иван* (who came? – Ivan) versus *Иван пришёл вчера* (when did he come? – yesterday).",
 "Russisch wird in vielen Ländern gesprochen – von Kaliningrad bis Wladiwostok, in Kasachstan, Kirgisistan, Israel, Deutschland und den USA. Überall klingt es etwas anders.": "Russian is spoken in many countries – from Kaliningrad to Vladivostok, in Kazakhstan, Kyrgyzstan, Israel, Germany, and the USA. It sounds a bit different everywhere.",
 "Russische Bewegungsverben kommen paarweise – für Muttersprachler ist der Unterschied so selbstverständlich wie für uns der Artikel.": "Russian verbs of movement come in pairs – for native speakers, the difference is as natural as articles are for us.",
 "Russische Konventionen nutzen": "Using Russian Conventions",
 "Russische Nachrichtentexte nutzen viele Passivformen – dadurch wirken sie sachlich und distanziert.": "Russian news texts often use passive forms – this makes them sound factual and detached.",
 "Russische Studenten feiern am 25. Januar den Tatjana-Tag – den offiziellen Feiertag aller Studierenden.": "Russian students celebrate Tatiana Day on January 25th – the official holiday for all students.",
 "Russland hat elf Zeitzonen – wenn in Moskau Mittag ist, gehen in Wladiwostok die Lichter an.": "Russia has eleven time zones – when it's noon in Moscow, the lights are coming on in Vladivostok.",
 "Russland ist das größte Land der Erde – elf Zeitzonen liegen zwischen Kaliningrad und Kamtschatka.": "Russia is the largest country in the world – eleven time zones stretch from Kaliningrad to Kamchatka.",
 "Sagen, dass etwas da ist – mit есть": "Saying that something is there – with есть",
