 "Sagt das Substantiv „unverändert\", bleibt auch das Adjektiv: *новый фильм*. Bekommt es *-у*, folgt das Adjektiv mit *-ую*: *интересную книгу*.": "If the noun stays \"unchanged\", so does the adjective: *новый фильм*. If it takes *-у*, the adjective follows with *-ую*: *интересную книгу*.",
 "Sätze bauen ohne „ist“ und ohne Artikel": "Building sentences without \"is\" and without articles",
 "Sätze ohne „ist“ und ohne Artikel": "Sentences Without \"Is\" and Without Articles",
 "Sätze verbinden mit который": "Connecting sentences with который",
 "Sätze wie „Das ist ein Haus“ mit zwei Wörtern bauen": "Building sentences like \"This is a house\" with two words",
 "Sätze wie „ich kenne dich“ bauen": "Building sentences like \"I know you\"",
 "Schau, was du kannst": "Look what you can do",
 "Schilder lesen, Chats verstehen, Tastatur einrichten": "Read signs, understand chats, set up your keyboard",
 "Schilder, Chats und die kyrillische Tastatur": "Signs, Chats and the Cyrillic Keyboard",
 "Schlag nur Wörter nach, die mehrfach vorkommen oder ohne die ein ganzer Absatz unklar bleibt. Der Rest erschließt sich – und bleibt so besser hängen.": "Only look up words that appear multiple times or without which an entire paragraph remains unclear. The rest will become clear through context – and will stick better that way.",
 "Schnee ist weiß, weil er aus Millionen Spiegeln besteht – jeder einzelne ist durchsichtig.": "Snow is white because it's made of millions of mirrors – each one is transparent.",
 "Schnelles Sprechen verstehen": "Understanding fast speech",
 "Schreibst du jemandem höflich, wird *Вы* großgeschrieben – wie unser „Sie“. Im Gespräch hört man keinen Unterschied, im Chat sieht man ihn sofort.": "When writing to someone formally, *Вы* is capitalised – as a mark of respect. In conversation, you won't hear a difference, but in a chat, you'll see it immediately.",
 "Sechs Buchstaben sehen aus wie unsere und klingen völlig anders.": "Six letters look like ours but sound completely different.",
