 "Sprecherhaltung erkennen": "Recognise the Speaker's Attitude",
 "Sprich ein „i“ – und zieh die Zunge nach hinten, als würdest du gleich „u“ sagen. Der Laut, der dabei entsteht, IST *ы*: *сын*, *рынок*, *быстро*.": "Say an \"i\" – and pull your tongue back as if you're about to say \"u\". The sound that comes out is *ы*: *сын*, *рынок*, *быстро*.",
 "Stadt & Bewegung": "City & Movement",
 "Stamm und Endung erkennen": "Recognising stem and ending",
 "Stärken und Schwächen benennen": "Naming Strengths and Weaknesses",
 "Statistik beschreiben": "Describing statistics",
 "Statistiken beschreiben": "Describing statistics",
 "Statt „ich habe“ sagt man „bei mir ist“ – у меня есть.": "Instead of 'I have', you say 'at me there is' – у меня есть.",
 "Statt *Я ответственный* lieber: *В прошлом проекте я отвечал за команду из пяти человек.* Konkrete Situationen wirken überall besser als Adjektive.": "Instead of *Я ответственный* (I am responsible), it's better to say: *В прошлом проекте я отвечал за команду из пяти человек.* (In the last project, I was in charge of a team of five people.) Specific situations are more effective than adjectives everywhere.",
 "Statt *я хорошо работал* lieber *я увеличил продажи на 20 процентов* – Zahlen wirken auch im russischen Bewerbungsgespräch.": "Instead of saying *я хорошо работал* (I worked well), it's better to say *я увеличил продажи на 20 процентов* (I increased sales by 20 percent) – numbers are impressive in Russian job interviews too.",
 "Statt sechs Fälle × acht Pronomen auswendig zu lernen, merk dir die häufigen Verbindungen: *у меня, со мной, к нему, о ней, для нас*. Die kommen im Alltag zu 90 % vor.": "Instead of memorising six cases × eight pronouns, remember the common combinations: *у меня, со мной, к нему, о ней, для нас*. These appear in everyday life 90% of the time.",
 "Stehen, liegen, hängen": "Standing, lying, hanging",
 "Stell dich vor (persönlich und beruflich), lies einen längeren Text, hör ein Audio in Normaltempo, diskutiere ein Problem, handle eine Lösung aus und präsentiere einen Plan – alles auf Russisch.": "Introduce yourself (personally and professionally), read a longer text, listen to audio at normal speed, discuss a problem, negotiate a solution, and present a plan – all in Russian.",
 "Stellenanzeigen entschlüsseln": "Decoding Job Advertisements",
 "Stellenanzeigen lesen": "Reading Job Advertisements",
 "Stellenanzeigen lesen, eine formelle E-Mail schreiben (*Уважаемый… С уважением*), ein Vorstellungsgespräch führen, im Meeting mitreden und ein Projekt präsentieren.": "Reading Job Advertisements, Writing a Formal Email (*Уважаемый… С уважением*), Conducting a Job Interview, Participating in a Meeting, and Presenting a Project.",
 "Stellenanzeigen und Lebenslauf": "Job Advertisements and CVs",
 "Stimmhafte Konsonanten verlieren am Wortende ihre Stimme: *хлеб* klingt „chlep“, *сад* klingt „sat“, *нож* klingt „nosch“. Geschrieben bleibt der weiche Buchstabe!": "Voiced consonants lose their voice at the end of a word: *хлеб* sounds like \"khlep\", *сад* sounds like \"sat\", *нож* sounds like \"nosh\". The soft letter remains in writing!",
 "Struktur erfassen": "Grasping the Structure",
 "Subjekt – Verb – Objekt: *Я читаю книгу*. Russisch kann umstellen, um etwas zu betonen – aber lern erst die neutrale Form. Sie ist nie falsch.": "Subject – Verb – Object: *Я читаю книгу*. Russian can rearrange to emphasize something – but first learn the neutral form. It's never wrong.",
 "Suffixe für Personen und Handlungen": "Suffixes for people and actions",
 "Superlative und Verstärkung": "Superlatives and Intensification",
