 "Unpersönliche Aussagen verstehen": "Understanding impersonal statements",
 "Unpersönliche Konstruktionen": "Impersonal constructions",
 "Unpersönliche Sätze bilden": "Forming impersonal sentences",
 "Unpersönliches (*мне кажется*, *мне нужно*), Kurzformen (*я готов*, *это важно*), die Partikeln *же*, *ведь*, *даже*, *только* für den Zwischenton – und die Wortstellung als Werkzeug, um zu betonen, worauf es dir ankommt. Damit erzählst du eine Geschichte und diskutierst sie danach.": "Impersonal expressions (*мне кажется*, *мне нужно*), short forms (*я готов*, *это важно*), particles *же*, *ведь*, *даже*, *только* for nuance – and word order as a tool to emphasise what matters to you. With these, you tell a story and discuss it afterwards.",
 "Unterkunft buchen": "Booking Accommodation",
 "Unternehmen und Arbeitsalltag": "The Company and Daily Work Life",
 "Unternehmensstrukturen benennen": "Naming Company Structures",
 "Unterwegs Probleme lösen": "Solve problems on the go",
