 "Vergangenes erfragen und verneinen": "Asking and negating in the past",
 "Vergangenes im Hören verstehen": "Understanding past events through listening",
 "Vergangenes zeitlich ordnen": "Ordering Past Events",
 "Vergangenheitsform + бы": "Past tense + бы",
 "Vergleiche die Zeiten: Im Tagebuch klingt der Abend perfekt, im Chat kam Tom zu spät. Texte erzählen aus einer Perspektive – erst der Vergleich zeigt, was wirklich war.": "Compare the times: In the diary, the evening sounds perfect, but in the chat, Tom was late. Texts tell stories from a perspective – only by comparing can you see what really happened.",
 "Vergleichen mit чем und den Kurzformen": "Comparing with чем and the short forms",
 "Verhandeln mit если": "Negotiating with если",
 "Verlauf oder Ergebnis?": "Process or result?",
 "Verlauf und Ergebnis unterscheiden": "Distinguishing ongoing action and result",
 "Verlauf und Wiederholung ausdrücken": "Expressing ongoing actions and repetition",
 "Verneinen – und dabei die Wortstellung im Griff behalten": "Negating – and keeping the word order under control",
 "Verneinung fast immer imperfektiv": "Negation almost always imperfective",
 "Verneinung im Aspekt richtig wählen": "Choosing the right aspect with negation",
 "Verneinung mit не und нет – und die neutrale Wortstellung": "Negation with не and нет – and the neutral word order",
 "Verpackungen und Mengen angeben": "Specifying packaging and quantities",
 "Verpflichtung: должен, надо, приходится": "Obligation: должен, надо, приходится",
 "Verschiedene Höflichkeitsstufen": "Different levels of politeness",
 "Verschleifungen und Reduktionen": "Blending and reductions",
 "Verschluckte Silben": "Swallowed syllables",
 "Verständlich schlägt perfekt": "Understandable beats perfect",
 "Verständlich sein statt perfekt": "Being understandable rather than perfect",
 "Verstehen, warum die Person im Dativ steht": "Understanding why the person is in the dative case",
 "Verstehen, warum es kein „haben\" gibt": "Understanding why there is no 'to have'",
 "Verwandte Wörter auf Anhieb verstehen": "Understanding Related Words Instantly",
 "Verwandte Wörter erkennen": "Recognising Related Words",
 "Viele Berufe haben eine weibliche Form: *учитель* → *учительница*. Andere gelten für alle: *врач* (Arzt/Ärztin), *инженер*. Im Zweifel: die männliche Form ist für beide okay.": "Many jobs have a feminine form: *учитель* → *учительница*. Others are the same for everyone: *врач* (doctor), *инженер* (engineer). If in doubt: the masculine form is okay for both.",
 "Vielfache": "Multiples",
 "Vielfache ausdrücken": "Expressing multiples",
 "Vielleicht, angeblich": "Maybe, allegedly",
 "Vier Abstufungen": "Four Levels",
 "Vier auf einen Streich": "Four in one go",
