 "Vier Formen": "Four forms",
 "Vier Formen wie das Adjektiv": "Four forms like the adjective",
 "Vier Formen wie Kurzadjektive": "Four forms like short adjectives",
 "Vier Präpositionen für Kommen und Gehen": "Four prepositions for coming and going",
 "Vokalreduktion: unbetontes о klingt wie a": "Vowel Reduction: Unstressed о sounds like a",
 "Volle Partizipien erkennen": "Recognising full participles",
 "Volle Stunden sagen": "Saying full hours",
