 "Wortstellung, Fokus und Intonation": "Word order, focus, and intonation",
 "Worüber sprechen wir?": "What are we talking about?",
 "Wunsch und Absicht unterscheiden": "Distinguishing between wishes and intentions",
 "Wünsche ausdrücken": "Expressing wishes",
