 "Zahl + Wort + *пожалуйста* funktioniert immer: *Два кофе, пожалуйста* – zwei Kaffee, bitte. Mehr Grammatik braucht ein Café nicht.": "Number + word + *пожалуйста* always works: *Два кофе, пожалуйста* – two coffees, please. No more grammar needed in a café.",
