 "Zeitung und Vertrag: Passiv (*было решено*). Gespräch: unpersönlich (*решили*). Präsentation, wenn dein Team Lob verdient: Aktiv (*мы разработали*).": "Newspaper and contract: Passive (*было решено*). Conversation: Impersonal (*решили*). Presentation, when your team deserves praise: Active (*мы разработали*).",
 "Zimmer buchen": "Booking a Room",
 "Zu *мама, папа, брат, сестра* aus Lektion 3 kommen jetzt *сын, дочь, жена, муж, дедушка, бабушка*. Damit stellst du jede Familie vor.": "To *мама, папа, брат, сестра* from Lesson 3, we now add *сын, дочь, жена, муж, дедушка, бабушка*. With these, you can introduce any family.",
 "Zu Besuch bringt man immer etwas mit – Blumen, Süßigkeiten oder Kuchen. Mit leeren Händen kommt niemand.": "When visiting, you always bring something – flowers, sweets, or cake. No one comes empty-handed.",
 "Zu Fuß идти/ходить, mit einem Fahrzeug ехать/ездить. Verwechseln fällt sofort auf.": "On foot идти/ходить, with a vehicle ехать/ездить. Mixing them up is immediately noticeable.",
 "Zu Fuß oder mit Fahrzeug – Russisch trennt das immer. Ein „Ich gehe nach Moskau\" gibt es nicht.": "On foot or by vehicle – Russian always distinguishes this. There's no 'I go to Moscow' in Russian.",
 "Zu Fuß und mit Fahrzeug trennen": "Distinguish on foot and by vehicle",
 "Zu Personen geht man mit *к* + Dativ: *к врачу, к другу, к маме*. Zu Orten mit *в* oder *на*. Menschen bekommen ihre eigene Präposition.": "You go to people with *к* + dative: *к врачу, к другу, к маме*. You go to places with *в* or *на*. People have their own preposition.",
 "Zu Verwandten sagt man oft nicht „meine Mutter“, sondern einfach мама – der Besitz ist sowieso klar.": "When talking about relatives, people often just say мама instead of \"my mother\" – the ownership is clear anyway.",
 "Zu wem, von wem": "To whom, from whom",
 "Zukunft und Konditional im Text erkennen": "Recognising Future and Conditional in Text",
 "Zum Du: *скажи, иди, дай*. Zum Sie (oder zu mehreren): dieselbe Form plus *-те*: *скажите, идите, дайте*. Einfacher geht es kaum.": "For informal: *скажи, иди, дай*. For formal (or plural): the same form plus *-те*: *скажите, идите, дайте*. It couldn't be simpler.",
 "Zum Freund: *как тебя зовут?* Zum Fremden: *как вас зовут?* – dieselbe du/Sie-Regel wie bei der Begrüßung. Einmal verstanden, überall anwendbar.": "To a friend: *как тебя зовут?* To a stranger: *как вас зовут?* – the same informal/formal rule as in greetings. Once understood, it applies everywhere.",
